class ICD10Service:
    @staticmethod
    def get_by_code(code: str) -> Optional[ICD10Entry]:
        return ICD10_DATABASE.get(code.strip())

    @staticmethod
    def search(query: str, limit: int = 50) -> List[ICD10Entry]:
        q = query.lower().strip()
        return [e for e in ICD10_DATABASE.values() if q in e.code.lower() or q in e.description.lower()][:limit]
